// 题即玩法 play-1 audit (docs/PLAY.md §10, docs/LEARN.md §18): the puzzle's choice items as ink targets, in a real page.
// A static server over this checkout at /game/ (as her App's bundle lays it out: the dev beacon stays off;
// songs/manifest.json — generated by `npm run music`, not in git — is answered with the bundle's `{ "tracks": {} }`),
// Chromium on software GL, ?quality=low, shadows / bloom off, the game clock frozen (debug.freeze) and stepped by hand.
//
//   node tools/learn/play-audit.mjs --view portrait|landscape|desktop [--learn w1d1 --gate 2] [--shots <dir>] [--frames 60]
//       portrait 390 × 844 touch (?from=app, as the App opens it) · landscape 844 × 390 touch · desktop 1280 × 720 mouse
//       Walks to the first gate (auto-walk), then while an M1 item is asked asserts: no question card (.iw-learn__panel
//       shown), match.paused false, learn.hold falsy, every object's projected box inside the safe area (the screen
//       minus the strip, 16 px each side), the camera framed; a WRONG pick (a tap on the object, or on the desktop fire with
//       the crosshair on it): the round flies, the answer is taken on the hit, coral object + the right one ringed + the
//       gate's lock coral + 「差一点：是 ___」 on the strip, learn:answer once with first = true; then every item RIGHT
//       (burst, 答对了) through both gates of the short level; no console errors, no 4xx. --frames N: the frame-time
//       sampler (debug.frameTimes) over N stepped frames of plain walking and N with an M1 question up, same stage.
//   node tools/learn/play-audit.mjs --script tools/learn/play-forms.json --query '?learn=w1d2&kind=race&short=1&fast=1' [--view …]
//       replays one of the existing play.mjs step scripts (until / wait / eval / evalFile / shot) — the other forms' audits —
//       with playwright (this box has no puppeteer-core)
// Run browsers one at a time: flock -w 9000 /tmp/ielts-browser.lock nice -n 10 node tools/learn/play-audit.mjs …
// (NODE_PATH must reach playwright; Chromium at /opt/pw-browsers/chromium or CHROME_PATH)
import http from 'node:http';
import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import { createRequire } from 'node:module';

const { chromium } = createRequire(import.meta.url)('playwright');
const ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '../..');
const args = process.argv.slice(2);
const opt = (k, d) => { const i = args.indexOf('--' + k); return i >= 0 ? args[i + 1] : d; };
const VIEW = opt('view', 'portrait'), SHOTS = opt('shots', null), SCRIPT = opt('script', null), FRAMES = +opt('frames', 0);
const LEARN_Q = opt('learn', 'w1d1'), GATE = +opt('gate', 2), BUDGET = +opt('budget', 900) * 1000;
const VIEWS = {
  portrait: { w: 390, h: 844, touch: true, app: true },
  landscape: { w: 844, h: 390, touch: true, app: false },
  desktop: { w: 1280, h: 720, touch: false, app: false },
};
const V = VIEWS[VIEW] || VIEWS.portrait;
const T0 = Date.now();
const say = (...a) => console.log(`[play-audit ${VIEW} ${((Date.now() - T0) / 1000).toFixed(1).padStart(5)}]`, ...a);
const MIME = { html: 'text/html; charset=utf-8', js: 'text/javascript; charset=utf-8', mjs: 'text/javascript; charset=utf-8', css: 'text/css; charset=utf-8', json: 'application/json; charset=utf-8', webp: 'image/webp', png: 'image/png', jpg: 'image/jpeg', svg: 'image/svg+xml', woff2: 'font/woff2', mp3: 'audio/mpeg', ogg: 'audio/ogg', wasm: 'application/wasm', txt: 'text/plain; charset=utf-8' };
const srv = http.createServer((q, r) => {
  let u = decodeURIComponent(new URL(q.url, 'http://x').pathname);
  if (!u.startsWith('/game/')) { r.writeHead(404); return r.end(); }
  u = u.slice('/game'.length);
  const p = path.join(ROOT, u);
  if (u === '/songs/manifest.json' && !fs.existsSync(p)) { r.writeHead(200, { 'content-type': MIME.json }); return r.end('{ "tracks": {} }'); }
  if (!p.startsWith(ROOT) || !fs.existsSync(p) || fs.statSync(p).isDirectory()) { r.writeHead(404); return r.end(); }
  r.writeHead(200, { 'content-type': MIME[path.extname(p).slice(1)] || 'application/octet-stream', 'cache-control': 'no-store' });
  fs.createReadStream(p).pipe(r);
});
await new Promise((ok) => srv.listen(0, '127.0.0.1', ok));
const base = `http://127.0.0.1:${srv.address().port}/game/`;
const browser = await chromium.launch({ executablePath: process.env.CHROME_PATH || '/opt/pw-browsers/chromium', args: ['--no-sandbox', '--ignore-gpu-blocklist', '--use-gl=angle', '--use-angle=swiftshader', '--enable-unsafe-swiftshader', '--autoplay-policy=no-user-gesture-required'] });
const watchdog = setTimeout(() => { say('WATCHDOG — out of budget'); finish(2); }, BUDGET);
const ctx = await browser.newContext({ viewport: { width: V.w, height: V.h }, deviceScaleFactor: 1, isMobile: V.touch, hasTouch: V.touch });
await ctx.addInitScript((touch) => { try { const k = 'inkwave.settings', v = JSON.parse(localStorage.getItem(k) || '{}'); Object.assign(v, { shadows: false, bloom: false, touchControls: touch ? 'on' : 'off' }); localStorage.setItem(k, JSON.stringify(v)); } catch (e) { /* none */ } }, V.touch);
const page = await ctx.newPage();
const bad = [], errs = [], fails = [], report = { view: VIEW, size: `${V.w}x${V.h}` };
page.on('response', (r) => { if (r.status() >= 400) bad.push(r.status() + ' ' + r.url().replace(base, '/game/')); });
page.on('requestfailed', (r) => { const u = r.url(); if (!/^blob:|^data:/.test(u)) bad.push('FAILED ' + u.replace(base, '/game/') + ' ' + ((r.failure() || {}).errorText || '')); });
page.on('console', (m) => { if (m.type() === 'error') errs.push('[console] ' + m.text()); });
page.on('pageerror', (e) => errs.push('[pageerror] ' + e.message));
const check = (ok, what, detail) => { if (!ok) fails.push(what + (detail ? ' — ' + (typeof detail === 'string' ? detail : JSON.stringify(detail)) : '')); say((ok ? 'ok   ' : 'FAIL ') + what + (detail && !ok ? ' ' + JSON.stringify(detail).slice(0, 400) : '')); return ok; };
const ev = (fn, ...a) => page.evaluate(fn, ...a);
const step = (ms = 16.7) => ev((m) => __inkwave.debug.step(m), ms);
async function shot(name) {
  if (!SHOTS) return;
  fs.mkdirSync(SHOTS, { recursive: true });
  const f = path.join(SHOTS, `${VIEW}-${name}.png`);
  await page.screenshot({ path: f, timeout: 180000 });
  say('shot', f);
}
async function finish(code) {
  clearTimeout(watchdog);
  report.fails = fails; report.badResponses = bad; report.errors = errs.filter((e) => !/Failed to load resource/.test(e) || !bad.length);
  console.log('\n[play-audit] REPORT ' + JSON.stringify(report, null, 1));
  console.log(`[play-audit] ${VIEW}: ${fails.length ? fails.length + ' FAILED' : 'all checks passed'} · 4xx ${bad.length} · console errors ${errs.length}`);
  try { await browser.close(); } catch (e) { /* gone */ }
  srv.close();
  process.exit(code != null ? code : (fails.length || bad.length || errs.length ? 1 : 0));
}

// ------------------------------------------------------------------------------------------------ an existing step script
if (SCRIPT) {
  const steps = JSON.parse(fs.readFileSync(path.resolve(ROOT, SCRIPT), 'utf8'));
  const q = opt('query', '?learn=w1d2&kind=race&short=1&fast=1') + '&quality=low&nofullscreen&noclips' + (V.app ? '&from=app' : '');
  say('script', SCRIPT, q);
  await page.goto(base + 'index.html' + q, { waitUntil: 'load', timeout: 180000 });
  for (const s of steps) {
    if (s.until) { try { await page.waitForFunction(s.until, null, { timeout: 420000, polling: 250 }); } catch { say('until timeout', s.until.slice(0, 100)); fails.push('until timeout'); } }
    if (s.wait) await new Promise((r) => setTimeout(r, s.wait));
    let code = s.eval;
    if (s.evalFile) code = fs.readFileSync(path.resolve(ROOT, s.evalFile), 'utf8');
    if (code) { try { const r = await page.evaluate(code); if (r !== undefined) console.log((s.log || 'eval') + ' ->', typeof r === 'string' ? r.slice(0, 3000) : JSON.stringify(r).slice(0, 3000)); } catch (e) { say('eval error', e.message); fails.push('eval error ' + e.message); } }
    if (s.shot && SHOTS) await shot(path.basename(SCRIPT, '.json'));
  }
  await finish();
}

// ------------------------------------------------------------------------------------------------ the M1 audit
// (?noclips: her App's recordings live at ../audio/ beside the game — not in this checkout; the device voice stands in)
const query = `?learn=${LEARN_Q}&kind=puzzle&short=1&gate=${GATE}&quality=low&nofullscreen&noclips` + (V.app ? '&from=app' : '');
say('open', query);
await page.goto(base + 'index.html' + query, { waitUntil: 'load', timeout: 180000 });
await page.waitForFunction(() => window.__inkwave && __inkwave.match && __inkwave.match.mode === 'learn' && __inkwave.match.state === 'playing' && __inkwave.match.learn, null, { timeout: 420000, polling: 250 });
say('level playing');
report.boot = await ev(() => { const F = __inkwave.match.learn; __inkwave.debug.freeze(); return { play: !!F.play, gates: F.gates.map((g) => ({ id: g.id, n: g.items.length, kinds: [...new Set(g.items.map((it) => it.meta.kind))] })), stage: __inkwave.mapDef && __inkwave.mapDef.id, touch: !!__inkwave.input.touch.active, flag: !!(F.play) }; });
say('boot', JSON.stringify(report.boot));
check(report.boot.play, 'LEARN.play is on: the puzzle has its play layer');

// a stretch of plain walking first (the frame-time baseline on this stage)
const sampleFrames = async (n, label) => {
  const r = await ev(async (n) => { const D = __inkwave.debug; D.frameTimes.start(); for (let i = 0; i < n; i++) { D.step(16.7); if (i % 5 === 4) await new Promise((r) => setTimeout(r, 0)); } return D.frameTimes.stop(); }, n);
  say('frames', label, JSON.stringify(r));
  return r;
};
if (FRAMES) {
  // plain walking: away from the first gate (W held, the camera turned round), so no question comes up while it is sampled
  await ev(() => { const F = __inkwave.match.learn, a = __inkwave.match.local, g = F.gates[0]; __inkwave.rig.yaw = Math.atan2(a.pos.x - g.pos.x, a.pos.z - g.pos.z); __inkwave.debug.key('KeyW', true); });
  report.framesWalk = await sampleFrames(FRAMES, 'walking');
  await ev(() => __inkwave.debug.key('KeyW', false));
}

// walk to the gate (2 s chunks, no render between) and let the objects come up and the camera frame them
const walk = async () => ev(() => {
  const D = __inkwave.debug, F = __inkwave.match.learn;
  if (!F.auto) F.autoWalk(true);
  let t = 0;
  while (!(F.play && F.play.cur && !F.play.cur.answered) && !(F.phase === 'ask' && __G.hud.learn._ask) && t < 120000 && F.phase !== 'done') { D.step(1000); t += 1000; }
  return { simMs: t, phase: F.phase, cur: F.cur };
});
const w1 = await walk();
say('walked', JSON.stringify(w1));
for (let i = 0; i < 6; i++) await step(250);   // 1.5 s: the pop-in and the framing ease
const state = () => ev(() => {
  const F = __inkwave.match.learn, P = F.play, m = __inkwave.match;
  const panel = document.querySelector('.iw-learn__panel');
  const pr = panel && panel.getBoundingClientRect();
  const strip = document.querySelector('.iw-ps__box'), sr = strip && strip.getBoundingClientRect();
  const lockCol = F.gates[F.cur] && F.gates[F.cur].mesh ? '#' + F.gates[F.cur].mesh.lock.material.color.getHexString() : null;
  return {
    paused: m.paused, hold: !!F.hold, panelShown: !!(pr && pr.width > 0 && pr.height > 0 && getComputedStyle(panel).display !== 'none'), cardUp: !!__G.hud.learn._ask,
    strip: strip && !document.querySelector('.iw-ps.is-off') ? { text: strip.innerText.replace(/\s+/g, ' ').trim(), rect: [sr.left, sr.top, sr.width, sr.height].map(Math.round), ok: !!document.querySelector('.iw-ps.is-ok'), bad: !!document.querySelector('.iw-ps.is-bad') } : null,
    W: innerWidth, H: innerHeight, dbg: P ? P.debug() : null, lockCol, locks: F.gates[F.cur] && F.gates[F.cur].locks,
    slots: P ? P.T.slots.filter((s) => s.on).map((s) => s.state) : [], answers: F.log.filter((e) => e.name === 'learn:answer'), cur: F.cur, phase: F.phase,
    touchLive: __inkwave.touch ? __inkwave.touch.enabled : null, rig: { yaw: +__inkwave.rig.yaw.toFixed(3), pitch: +__inkwave.rig.pitch.toFixed(3) },
  };
});
const checkAsked = async (label) => {
  const s = await state();
  const d = s.dbg;
  check(d && d.asking && !d.answered, `${label}: an M1 item is asked (${d && d.item}, ${d && d.n} ${d && d.banner ? 'banners' : 'balls'})`, d);
  check(!s.panelShown && !s.cardUp, `${label}: no question card (.iw-learn__panel not shown)`);
  check(s.paused === false, `${label}: match.paused === false`);
  check(!s.hold, `${label}: learn.hold falsy`);
  check(s.touchLive !== false || !V.touch, `${label}: the touch layer stays live`);
  check(!!s.strip && s.strip.rect[3] > 0, `${label}: the strip is up: 「${s.strip && s.strip.text}」`);
  const safe = { x: 16, y: s.strip ? s.strip.rect[1] + s.strip.rect[3] : 0, w: s.W - 32, h: s.H - (s.strip ? s.strip.rect[1] + s.strip.rect[3] : 0) };
  const boxes = (d && d.projected || []).map((q) => (q.kind === 'ball' ? { x: Math.min(q.cx - q.r, q.label.x), y: q.cy - q.r, w: Math.max(q.cx + q.r, q.label.x + q.label.w) - Math.min(q.cx - q.r, q.label.x), h: q.label.y + q.label.h - (q.cy - q.r) } : { x: q.x, y: q.y, w: q.w, h: q.h }));
  const out = boxes.filter((b) => !(b.x >= safe.x - 1 && b.y >= safe.y - 1 && b.x + b.w <= safe.x + safe.w + 1 && b.y + b.h <= safe.y + safe.h + 1));
  check(boxes.length === (d && d.n) && !out.length, `${label}: every object's projected box inside the safe area (${boxes.length} objects)`, { safe, boxes: boxes.map((b) => [b.x, b.y, b.w, b.h].map(Math.round)), out });
  report[label] = { item: d && d.item, labels: d && d.labels, banner: d && d.banner, strip: s.strip, safe, boxes: boxes.map((b) => [b.x, b.y, b.w, b.h].map(Math.round)), framing: { D: d && d.D, pitch: d && d.pitch, rig: s.rig }, atlases: d && d.atlases, calls: d && d.calls };
  return s;
};
// pick object k: a tap on its projected centre (touch), or the crosshair laid on it and fire pressed (desktop)
const pick = async (k) => {
  if (V.touch) {
    const c = await ev((k) => { const q = __inkwave.match.learn.play.debug().projected.find((q) => q.i === k); return q && (q.kind === 'ball' ? { x: q.cx, y: q.cy } : { x: q.x + q.w / 2, y: q.y + q.h / 2 }); }, k);
    if (!c) return false;
    await page.touchscreen.tap(Math.round(c.x), Math.round(c.y));
    return true;
  }
  // desktop: aim (the gameplay camera's centre ray through the object's centre: a couple of passes, the camera follows) then a click's worth of fire
  for (let pass = 0; pass < 4; pass++) {
    await ev((k) => { const P = __inkwave.match.learn.play, rig = __inkwave.rig, cam = rig.gameCam; const c = P.T.slots[k].pos; const dx = c.x - cam.position.x, dy = c.y - cam.position.y, dz = c.z - cam.position.z; rig.yaw = Math.atan2(dx, dz); rig.pitch = Math.atan2(dy, Math.hypot(dx, dz)); }, k);
    await step(16.7);
  }
  const on = await ev(() => __inkwave.match.learn.play._crosshair());
  if (!check(on === k, `desktop: the crosshair is on object ${k}`, { on })) return false;
  await ev(() => __inkwave.debug.fire(true)); await step(16.7); await ev(() => __inkwave.debug.fire(false));
  return true;
};
// step the sim until the asked item has its verdict (the round has to fly and land)
const untilVerdict = async () => {
  for (let i = 0; i < 90; i++) { const v = await ev(() => { const P = __inkwave.match.learn.play; return P.cur && P.cur.verdict; }); if (v) return v; await step(16.7); }
  return null;
};

const s1 = await checkAsked('q1');
await shot('m1-question');
if (FRAMES) {
  // the same frames with the M1 question up (objects, strip, the atlas) while she stands at the gate
  report.framesM1 = await sampleFrames(FRAMES, 'M1 question up');
  if (report.framesWalk) report.framesDelta = { p50: +(report.framesM1.p50 / report.framesWalk.p50 - 1).toFixed(3), p95: +(report.framesM1.p95 / report.framesWalk.p95 - 1).toFixed(3) };
}
const d1 = s1.dbg, wrongK = (d1.rightIndex + 1) % d1.n;
const answers0 = s1.answers.length;
const tShot0 = await ev(() => __inkwave.match.learn.t);
check(await pick(wrongK), `a wrong pick: object ${wrongK} (${JSON.stringify(d1.labels[wrongK])}) — the right one is ${d1.rightIndex}`);
const v1 = await untilVerdict();
const s2 = await state();
const lg = s2.dbg.log, fire = lg.find((e) => e.ev === 'fire'), hit = lg.find((e) => e.ev === 'hit' && e.deliberate), ans = lg.find((e) => e.ev === 'answer');
check(!!v1 && v1.ok === false && v1.k === wrongK, 'the round landed on it and the answer was taken: wrong', { v1, log: lg.slice(-6) });
check(!!fire && !!hit && !!ans && hit.t === ans.t, `the answer is taken on the hit frame (tap → round leaves ${fire ? (fire.t - tShot0).toFixed(2) : '?'} s, round → hit ${fire && hit ? (hit.t - fire.t).toFixed(2) : '?'} s)`);
report.timing = { tapToFire: fire && +(fire.t - tShot0).toFixed(3), fireToHit: fire && hit && +(hit.t - fire.t).toFixed(3), hitToAnswer: hit && ans && +(ans.t - hit.t).toFixed(3) };
const newAns = s2.answers.slice(answers0);
check(newAns.length === 1 && newAns[0].first === true && newAns[0].ok === false, 'learn:answer once, first of the day (recordFirst wrote it)', newAns);
check(s2.slots[wrongK] === 'coral', 'the picked object turned coral', s2.slots);
check(s2.slots[d1.rightIndex] === 'right', 'the right object is ringed in her ink', s2.slots);
check(s2.locks === 1 && /^#f08a7a$/i.test(s2.lockCol || ''), `the gate's lock marker: 1 lock, coral (${s2.lockCol})`);
check(!!s2.strip && s2.strip.bad && /^差一点：是 /.test(s2.strip.text), `the strip: 「${s2.strip && s2.strip.text}」`);
check(s2.paused === false && !s2.panelShown, 'still no pause, no card');
await step(16.7 * 6);
await shot('m1-wrong');
report.wrong = { verdict: v1, strip: s2.strip && s2.strip.text, slots: s2.slots, lock: s2.lockCol };

// every item right from here (the retry of the missed one comes back reshuffled — first = false: it was answered today)
let rights = 0, shotRight = false, guard = 0, firstsRight = [];
while (guard++ < 14) {
  // the next question (or the next gate: walk there)
  for (let i = 0; i < 80; i++) { const st = await ev(() => { const F = __inkwave.match.learn, P = F.play; return { asking: !!(P.cur && !P.cur.answered), phase: F.phase, card: !!__G.hud.learn._ask, done: F.phase === 'done' || !!document.querySelector('.iw-learn.is-done') }; }); if (st.asking || st.done || st.card) break; if (st.phase === 'walk') await walk(); else await step(100); }
  const st = await ev(() => { const F = __inkwave.match.learn, P = F.play; return { asking: !!(P.cur && !P.cur.answered), done: F.phase === 'done' || !!document.querySelector('.iw-learn.is-done'), card: !!__G.hud.learn._ask, cur: F.cur }; });
  if (st.done || !st.asking) { if (st.card) say('a card item came (not a play kind yet) — stopping here'); break; }
  for (let i = 0; i < 5; i++) await step(250);
  const s = await checkAsked('q' + (rights + 2));
  if (s.dbg.banner && !report.bannerShot) { report.bannerShot = true; await shot('m1-banners'); }
  const before = s.answers.length;
  await pick(s.dbg.rightIndex);
  const v = await untilVerdict();
  const sv = await state();
  check(!!v && v.ok === true, `right pick on ${s.dbg.item}: 答对了`, v);
  check(!!sv.strip && sv.strip.ok && /^答对了/.test(sv.strip.text), `the strip flashes her ink: 「${sv.strip && sv.strip.text}」`);
  const na = sv.answers.slice(before);
  check(na.length === 1, `learn:answer once (first = ${na[0] && na[0].first})`, na);
  firstsRight.push({ item: s.dbg.item, first: na[0] && na[0].first });
  if (!shotRight) { shotRight = true; await step(16.7 * 4); await shot('m1-right'); }
  rights++;
  for (let i = 0; i < 8; i++) await step(100);
}
report.rights = rights; report.firstsRight = firstsRight;
const end = await ev(() => { const F = __inkwave.match.learn; return { cur: F.cur, gates: F.gates.length, opened: F.gates.filter((g) => g.state === 'open').length, log: F.log.map((e) => e.name.replace('learn:', '') + (e.ok != null ? (e.ok ? '+' : '-') : '') + (e.first ? '*' : '') + (e.opened ? '(open)' : '')).join(' '), cov: __G.paint.coverage().map((c) => +c.toFixed(4)), ev: Object.keys(JSON.parse(localStorage.getItem('inkwave:learn:v1') || '{"ev":{}}').ev) }; });
say('end', JSON.stringify(end));
report.end = end;
check(end.opened >= 1, `gates opened: ${end.opened} / ${end.gates}`);
check(rights >= 2, `answered right: ${rights}`);

await finish();
